package io.github.diodeme.ji.export;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.artifact.ArtifactId;
import io.github.diodeme.ji.artifact.ArtifactReference;
import io.github.diodeme.ji.artifact.ArtifactScope;
import io.github.diodeme.ji.session.SessionSnapshot;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

final class SessionExporterTest {
    private static final Instant NOW = Instant.parse("2026-09-04T00:00:00Z");

    @Test
    void jsonlGoldenIsDeterministicReadableAndExplicitlyNotABackup() {
        byte[] actual = new SessionExporter().exportJsonl(snapshot(), ExportOptions.withoutArtifacts());
        String text = new String(actual, StandardCharsets.UTF_8);
        assertEquals("""
                {"format":"ji.session.export","version":1,"backup":false,"sessionId":"session-1","revision":3}
                {"type":"message","id":"m-user","role":"user","createdAt":"2026-09-04T00:00:00Z","text":"<script>alert(&quot;x&quot;)</script> & secret"}
                {"type":"message","id":"m-assistant","role":"assistant","createdAt":"2026-09-04T00:00:00Z","text":"Safe response"}
                {"type":"summary","usage":{"inputTokens":2,"outputTokens":3,"cacheReadTokens":0,"cacheWriteTokens":0,"totalTokens":5},"activeRun":null}
                """, text);
        assertFalse(text.contains("workingDirectory"));
        assertFalse(text.contains("credential"));
    }

    @Test
    void htmlGoldenEscapesEveryDynamicFieldAndUsesRestrictiveCspWithoutScripts() {
        String html = new String(new SessionExporter().exportHtml(snapshot(), ExportOptions.withoutArtifacts()), StandardCharsets.UTF_8);
        assertTrue(html.contains("Content-Security-Policy"));
        assertTrue(html.contains("default-src &#39;none&#39;; img-src &#39;self&#39;; style-src &#39;unsafe-inline&#39;; base-uri &#39;none&#39;; form-action &#39;none&#39;"));
        assertTrue(html.contains("&lt;script&gt;alert(&amp;quot;x&amp;quot;)&lt;/script&gt; &amp; secret"));
        assertFalse(html.contains("<script"));
        assertFalse(html.contains("javascript:"));
        assertFalse(html.contains("data:"));
        assertTrue(html.contains("This readable export is not a backup"));
    }

    @Test
    void artifactReferencesAreOptionalAuthorizedLinksAndNeverInlineRawBytes() {
        var reference = new ArtifactReference(
                new ArtifactId("sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"),
                new ArtifactScope("host-1", "workspace-1", "session-1"), "image/png", 4, "preview.png");
        var exporter = new SessionExporter();

        String without = new String(exporter.exportHtml(snapshot(), ExportOptions.withoutArtifacts()), StandardCharsets.UTF_8);
        String with = new String(exporter.exportHtml(snapshot(), new ExportOptions(List.of(reference), true)), StandardCharsets.UTF_8);
        assertFalse(without.contains("sha256:"));
        assertTrue(with.contains("artifacts/sha256%3A0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"));
        assertTrue(with.contains("preview.png"));
        assertFalse(with.contains("base64"));
    }

    private static SessionSnapshot snapshot() {
        return new SessionSnapshot("session-1", 3, new ModelRef("faux", "fixture-model"), "C:/secret/workspace",
                List.of(
                        new Message("m-user", Message.Role.USER,
                                List.of(new Content.Text("<script>alert(&quot;x&quot;)</script> & secret")), NOW),
                        new Message("m-assistant", Message.Role.ASSISTANT,
                                List.of(new Content.Text("Safe response")), NOW)),
                new Usage(2, 3, 0, 0, 5), Optional.empty());
    }
}
